// Creating sprite and its states
uses GraphABC,ABCSprites,ABCObjects,Events;

var s: SpriteABC;

begin
  Window.Title := 'Sprite creation';
  SetWindowSize(400,300);
  CenterWindow;

  // Creating sprite and adding frames to it
  s := new SpriteABC(150,100,'SpriteFrames\multi1.bmp');
  s.Add('SpriteFrames\multi2.bmp');
  s.Add('SpriteFrames\multi3.bmp');
  s.Add('SpriteFrames\multi2.bmp');
  s.Add('SpriteFrames\multi4.bmp');
  s.Add('SpriteFrames\multi5.bmp');

  // Adding states to sprite
  s.AddState('fly',4); // Fly - 4 frames
  s.AddState('stand',1); // Stand - 1 frame
  s.AddState('sit',1); // Sit - 1 frame

  // Setting sprite animation speed (1..10)
  s.Speed := 9;

  // Saving sprite to "long" image and creating sprite info file
  s.SaveWithInfo('spr.png');
end.

// Switching sprite states with mouse click
uses GraphABC,ABCSprites,ABCObjects,Events;

var
  s: SpriteABC;
  t: TextABC;

procedure MyMouseDown(x,y,mb: integer);
begin
  if s.PtInside(x,y) then
  begin
    // Transition to next sprite state
    if s.State<s.StateCount then
      s.State := s.State + 1
    else s.State := 1;
    t.Text := 'Sprite state: ' + s.StateName;
  end;
end;

begin
